const grid=document.querySelector('#listingGrid'),toast=document.querySelector('#toast'),pageMain=document.querySelector('main'),homeMarkup=pageMain.innerHTML;
const DEFAULT_AGENT_AVATAR='data:image/svg+xml,%3Csvg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 240 240"%3E%3Crect width="240" height="240" fill="%23dfe9e2"/%3E%3Ccircle cx="120" cy="86" r="42" fill="%2372807b"/%3E%3Cpath d="M42 222c8-55 35-82 78-82s70 27 78 82" fill="%2372807b"/%3E%3C/svg%3E';
const agentBadge=active=>active?'<span class="agent-badge" role="img" aria-label="Verified agent" title="Verified agent">✓</span>':'';
const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const safeMediaUrl=value=>{const url=String(value||'');return /^(?:https?:\/\/|\/|data:image\/(?:svg\+xml|png|jpeg|webp);)/i.test(url)?url:DEFAULT_AGENT_AVATAR};
const agentAvatar=(src,_active,alt='')=>`<img class="search-result-avatar" src="${escapeHtml(safeMediaUrl(src))}" alt="${escapeHtml(alt)}" loading="lazy">`;
async function recordPostView(id,node){if(!node||node.dataset.viewed==='true')return;const counter=node.querySelector('[data-post-views],[data-views]');try{const result=await apiJson(`/api/listings/${encodeURIComponent(id)}/view`,{method:'POST',cache:'no-store'});node.dataset.viewed='true';if(counter&&result.views!==undefined)counter.textContent=`${result.views} views`}catch(error){delete node.dataset.viewed;console.warn('StayNest view tracking failed',error.message)}}
async function togglePostLike(id,node){try{const liked=node.dataset.liked==='true',csrf=(await apiJson('/api/auth/csrf')).token,result=await apiJson(`/api/listings/${id}/like`,{method:liked?'DELETE':'POST',headers:{'X-CSRF-Token':csrf}});node.dataset.liked=String(result.liked);node.classList.toggle('liked',result.liked);const counter=node.querySelector('[data-post-likes]');if(counter)counter.textContent=`${result.likes} likes`}catch(error){showToast(error.message)}}
function setupPostEngagement(root){root.querySelectorAll('[data-post-id]').forEach(post=>{recordPostView(post.dataset.postId,post);post.addEventListener('pointerenter',()=>recordPostView(post.dataset.postId,post),{once:true});post.addEventListener('click',()=>recordPostView(post.dataset.postId,post),{once:true});post.querySelector('[data-post-like]')?.addEventListener('click',event=>{event.stopPropagation();togglePostLike(post.dataset.postId,post)})})}
let currentUser=null;
function requireAccount(action='use this feature'){if(currentUser)return true;openModal(`<p class="eyebrow">Members only</p><h2>Sign in to ${action}</h2><p>Create a free StayNest account or sign in to access profiles, bookings, messaging, saved homes, and personalized features.</p><div class="auth-prompt-actions"><button class="primary" id="promptSignup">Create an account <span>→</span></button><button class="outline-btn" id="promptLogin">Already have an account? Sign in</button></div>`);content.querySelector('#promptSignup').onclick=()=>auth('signup');content.querySelector('#promptLogin').onclick=()=>auth('login');return false}
const savedIds=new Set(JSON.parse(localStorage.getItem('staynest_saved')||'[]'));
const bookings=JSON.parse(localStorage.getItem('staynest_bookings')||'[]');
function updatePersonalGreeting(user){const greeting=document.querySelector('#personalGreeting'),detail=document.querySelector('#personalGreetingDetail');if(!greeting||!detail)return;const hour=new Date().getHours(),timeGreeting=hour<5?'Good night':hour<12?'Good morning':hour<18?'Good afternoon':'Good evening';if(user?.firstName){greeting.textContent=`${timeGreeting}, ${user.firstName}`;detail.textContent='Your StayNest recommendations are ready';}else{greeting.textContent=`${timeGreeting}`;detail.textContent='Discover homes made for real life';}}
async function apiJson(url, options={}){let response;try{response=await fetch(url,{credentials:'same-origin',cache:'no-store',...options})}catch(error){throw new Error('StayNest is temporarily unavailable. Please make sure the app is running and try again.')}const text=await response.text();let data={};try{data=text?JSON.parse(text):{}}catch{throw new Error(response.status===404?'The requested StayNest service could not be found. Refresh the page and try again.':response.status===429?'Too many attempts. Please wait a few minutes and try again.':response.ok?'The server returned an invalid response.':`StayNest could not complete the request (HTTP ${response.status}).`)}if(!response.ok){if(response.status===429)throw new Error('Too many attempts. Please wait a few minutes and try again.');throw new Error(data.error||`StayNest could not complete the request (HTTP ${response.status}).`)}return data}
function render(filter='all'){const data=filter==='popular'?listings.filter(x=>+x.rating>4.9):filter==='new'?listings.filter(x=>x.tag.includes('New')):filter==='all'?listings:listings.filter(x=>x.type===filter);grid.innerHTML=data.map(x=>`<article class="listing-card reveal-on-scroll is-visible"><div class="listing-photo" style="background-image:url('${x.image}')"><button class="heart" data-id="${x.id}" aria-label="Save ${x.title}">♡</button>${x.tag?`<span class="rating">${x.tag}</span>`:''}</div><div class="listing-info"><h3>${x.title}</h3><div class="listing-meta">${x.location} · ${x.type==='short'?'Entire place':'Monthly rental'}</div><div class="listing-price"><strong>${x.price}</strong> ${x.type==='short'?'/ night':'/ month'} <span class="listing-meta"> · ★ ${x.rating}</span></div></div></article>`).join('');grid.querySelectorAll('.heart').forEach(btn=>btn.addEventListener('click',()=>{if(!requireAccount('save homes'))return;btn.classList.toggle('saved');btn.textContent=btn.classList.contains('saved')?'♥':'♡';showToast(btn.classList.contains('saved')?'Saved to your wishlist':'Removed from wishlist')}));grid.querySelectorAll('.listing-card').forEach(card=>card.addEventListener('click',e=>{if(e.target.closest('.heart'))return;const item=listings.find(x=>x.id===+card.querySelector('.heart').dataset.id);openListing({...item,isDemo:true})}))}
function showToast(message){toast.textContent=message;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2600)}
const modal=document.querySelector('#modal'),content=document.querySelector('#modalContent');
const nativeInnerHTML=Object.getOwnPropertyDescriptor(Element.prototype,'innerHTML');
const safeMarkup=value=>{
  const template=document.createElement('template');
  template.innerHTML=String(value??'');
  template.content.querySelectorAll('script,iframe,object,embed,link,style').forEach(node=>node.remove());
  template.content.querySelectorAll('*').forEach(node=>{
    [...node.attributes].forEach(attribute=>{
      const name=attribute.name.toLowerCase(), value=attribute.value.trim();
      if(name.startsWith('on')||name==='style'||(['src','href','action','formaction','xlink:href'].includes(name)&&/^(?:javascript:|vbscript:|data:(?!image\/(?:svg\+xml|png|jpeg|webp);))/i.test(value))) node.removeAttribute(attribute.name);
    });
  });
  return template.innerHTML;
};
const setSafeMarkup=(element,markup)=>nativeInnerHTML.set.call(element,safeMarkup(markup));
if(pageMain&&nativeInnerHTML)Object.defineProperty(pageMain,'innerHTML',{configurable:true,get:()=>nativeInnerHTML.get.call(pageMain),set:value=>setSafeMarkup(pageMain,value)});
function closeModal(){modal.classList.remove('open');document.body.classList.remove('modal-open')}
function openModal(html){setSafeMarkup(content,html);modal.classList.add('open');document.body.classList.add('modal-open');const form=content.querySelector('form');if(form&&!form.dataset.auth)form.addEventListener('submit',e=>{e.preventDefault();closeModal();showToast('Thanks — your request has been received.');});}
function openAdminGate(){openModal(`<p class="eyebrow">Private access</p><h2>Administrator sign in</h2><p>This control center is available only through the private StayNest access gate.</p><form id="adminGateForm"><label>Username</label><input name="username" autocomplete="username" required><label>Password</label><input name="password" type="password" autocomplete="current-password" required><p class="form-error" role="alert" aria-live="polite"></p><button class="primary" type="submit">Open admin control <span>→</span></button></form>`);content.querySelector('#adminGateForm').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;const button=form.querySelector('button');button.disabled=true;try{await apiJson('/api/admin/gate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:form.elements.username.value,password:form.elements.password.value})});window.location.href='/admin.html'}catch(error){form.querySelector('.form-error').textContent=error.message;button.disabled=false}})}
document.querySelectorAll('.brand').forEach(brand=>brand.addEventListener('dblclick',event=>{event.preventDefault();openAdminGate()}));
function openListing(x){if(currentUser?.roles?.includes('agent')){openModal(`<p class="eyebrow">Agent account</p><h2>Booking is for tenants</h2><p>Agent accounts manage listings and booking requests. Sign in with a tenant account to request a stay.</p>`);return}if(x.isDemo){openModal(`<p class="eyebrow">Preview home</p><h2>${x.title}</h2><p>${x.location} · ★ ${x.rating} (${x.reviews} reviews)</p><div class="listing-photo" style="height:180px;background-image:url('${x.image}');margin:20px 0"></div><p>This is a featured preview. Search for this home to request a booking from its assigned agent.</p>${currentUser?.roles?.includes('tenant')?'<p class="form-error">Search for this home to request a booking.</p>':'<button class="primary" id="loginToBook">Sign in to book <span>→</span></button>'}`);if(!currentUser)content.querySelector('#loginToBook').onclick=()=>auth('login');return}if(!currentUser&&!requireAccount('request a booking'))return;if(!currentUser?.roles?.includes('tenant'))return;openModal(`<p class="eyebrow">${x.tag||'Verified home'}</p><h2>${x.title}</h2><p>${x.location} · ★ ${x.rating} (${x.reviews} reviews)</p><div class="listing-photo" style="height:180px;background-image:url('${x.image||x.coverUrl||DEFAULT_AGENT_AVATAR}');margin:20px 0"></div><p>Send a booking request to the assigned agent. Your dates are held while the agent reviews the request.</p><form id="bookingForm"><label>Check-in</label><input name="checkIn" type="date" required><label>Check-out</label><input name="checkOut" type="date" required><label>Guests</label><input name="guests" type="number" min="1" max="20" value="1" required><p class="form-error" role="alert"></p><button class="primary" type="submit">Request to book <span>→</span></button></form>`);content.querySelector('#bookingForm').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;try{const csrf=(await apiJson('/api/auth/csrf')).token;const result=await apiJson('/api/bookings',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({listingId:x.id,checkIn:form.elements.checkIn.value,checkOut:form.elements.checkOut.value,guests:Number(form.elements.guests.value)})});closeModal();showToast(`Booking request ${result.bookingCode} sent to the agent`)}catch(error){form.querySelector('.form-error').textContent=error.message}})}
function auth(mode){const host=mode==='host';let signup=mode==='signup'||host;const renderAuth=()=>{openModal(`<p class="eyebrow">${host?'Join as an agent':signup?'Join StayNest':'Welcome to StayNest'}</p><h2>${host?'Start managing homes':signup?'Create your account':'Welcome back'}</h2><p>${signup?'Choose Tenant to book homes or Agent to manage properties.':'Sign in to access your bookings, messages, profile, and role workspace.'}</p><form data-auth="${signup?'register':'login'}">${signup?`<label>I want to</label><select name="role" required><option value="tenant">Tenant — rent or book a home</option><option value="agent" ${host?'selected':''}>Agent — manage properties and bookings</option></select><label>First name</label><input name="firstName" autocomplete="given-name" required><label>Last name</label><input name="lastName" autocomplete="family-name" required>`:''}<label>Email address</label><input name="email" type="email" autocomplete="email" placeholder="you@example.com" required><label>Password</label><input name="password" type="password" autocomplete="${signup?'new-password':'current-password'}" minlength="12" placeholder="At least 12 characters" required>${!signup?'<label>MFA code (if enabled)</label><input name="mfaCode" inputmode="numeric" autocomplete="one-time-code">':''}<label class="check-row"><input name="rememberMe" type="checkbox"> Remember me on this device</label><p class="form-error" role="alert" aria-live="polite"></p><button class="primary" type="submit">${signup?'Create account':'Sign in'} <span>→</span></button></form><p class="auth-switch">${signup?'Already have an account?':'New to StayNest?'} <button type="button" id="authSwitch">${signup?'Sign in':'Create an account'}</button></p>`);const form=content.querySelector('form'),submit=form.querySelector('button[type="submit"]'),errorBox=form.querySelector('.form-error');form.addEventListener('submit',async e=>{e.preventDefault();errorBox.textContent='';submit.disabled=true;submit.classList.add('loading');const data=Object.fromEntries(new FormData(form));data.rememberMe=Boolean(form.elements.rememberMe.checked);try{const csrf=await apiJson('/api/auth/csrf');const result=await apiJson(`/api/auth/${form.dataset.auth}`,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf.token},body:JSON.stringify(data)});if(result.mfaRequired){errorBox.textContent='Enter the six-digit authenticator code to continue.';form.querySelector('[name="mfaCode"]').focus();return}if(result.pendingApproval){closeModal();showToast('Agent registration submitted — founder approval is required before sign-in.');return}closeModal();await updateAuthControls((await apiJson('/api/auth/me')).user);showToast(signup?'Account created — you are now signed in.':'Signed in successfully.');showRoleDashboard(result.roles||[data.role]);}catch(error){errorBox.textContent=error.message;showToast(error.message)}finally{submit.disabled=false;submit.classList.remove('loading')}});content.querySelector('#authSwitch').onclick=()=>{signup=!signup;renderAuth()}};renderAuth()}
async function showRoleDashboard(roles){const role=roles.includes('agent')?'agent':'tenant';let data={};try{data=await apiJson(role==='agent'?'/api/agent/summary':'/api/account/summary')}catch(error){showToast(error.message);return}const contentByRole=role==='agent'?{title:'Agent workspace',intro:'Manage assigned homes and booking operations.',items:[`${data.assignedListings||0} assigned listings`,` ${data.pendingBookings||0} pending booking requests`,'Create a listing','Upload identity documents','Manage listing media']}:{title:'Your tenant workspace',intro:'Book homes and manage your stays from one secure account.',items:[`${data.upcomingBookings||0} upcoming bookings`,`${data.savedHomes||0} saved homes`,`${data.searchAlerts||0} active search alerts`,'Messages with agents','Reviews and ratings']};openModal(`<p class="eyebrow">${role} workspace</p><h2>${contentByRole.title}</h2><p>${contentByRole.intro}</p><div class="feature-list">${contentByRole.items.map((item,index)=>`<div><b>0${index+1}</b><span><strong>${item}</strong><small>Available from your authenticated ${role} account</small></span></div>`).join('')}</div>${role==='agent'?'<button class="primary" id="createListingAction">Create listing <span>→</span></button><button class="outline-btn" id="bookingRequestsAction">Review booking requests</button><button class="outline-btn" id="profileAction">Manage public profile</button>':'<button class="primary" id="bookingsAction">Open my bookings <span>→</span></button>'}`);content.querySelector('#createListingAction, #bookingsAction').addEventListener('click',()=>{if(role==='agent')openAgentListingForm();else loadTenantBookings()});content.querySelector('#bookingRequestsAction')?.addEventListener('click',loadAgentBookings);content.querySelector('#profileAction')?.addEventListener('click',openOwnAgentProfile)}
async function openOwnAgentProfile(){const me=await apiJson('/api/auth/me');document.body.classList.add('role-view');history.replaceState({},'',`/index.html?view=agent&agent=${me.user.id}`);openAgentProfile(me.user.id,true)}
async function openOwnTenantProfile(){document.body.classList.add('role-view');history.replaceState({},'','/index.html?view=tenant');const result=await apiJson('/api/tenant/profile');const {profile,following,wishlist}=result;pageMain.innerHTML=`<section class="agent-page tenant-page"><div class="agent-page-top"><button class="outline-btn" id="tenantBackHome">← Explore StayNest</button><span class="eyebrow">Your private StayNest profile</span></div><div class="agent-page-hero"><img class="agent-page-avatar" src="${profile.avatarUrl||DEFAULT_AGENT_AVATAR}" alt="${profile.firstName} ${profile.lastName}"><div class="agent-page-copy"><p class="eyebrow">Tenant profile</p><h1>${profile.firstName} ${profile.lastName}</h1><p class="agent-page-bio">${profile.bio||'Your saved homes and trusted agents, all in one place.'}</p><div class="agent-page-stats"><span><strong>${wishlist.length}</strong>saved homes</span><span><strong>${following.length}</strong>following</span></div><p class="agent-page-contact">${profile.email}</p><div class="agent-profile-actions"><button class="primary" id="editTenantProfile">Edit profile <span>→</span></button><button class="outline-btn" id="tenantBookingsProfile">My bookings</button></div></div></div><div class="tenant-sections"><div><div class="agent-page-toolbar"><h2>Following</h2><span>Agents you trust</span></div>${following.length?following.map(agent=>`<button class="search-result" data-agent-id="${agent.id}">${agentAvatar(agent.profileImageUrl,agent.badgeLabel,`${agent.firstName} ${agent.lastName}`)}<span><strong>${agent.firstName} ${agent.lastName}</strong><small>${agent.bio||'StayNest agent'}</small></span></button>`).join(''):'<p class="empty-copy">You are not following any agents yet. Explore an agent profile to follow them.</p>'}</div><div><div class="agent-page-toolbar"><h2>Wishlist</h2><span>Homes you saved</span></div><div class="tenant-wishlist">${wishlist.length?wishlist.map(home=>`<article class="search-result"><img src="${home.coverUrl||DEFAULT_AGENT_AVATAR}" alt=""><span><strong>${home.title}</strong><small>${home.city} · ${home.currency} ${home.nightlyPrice||home.monthlyPrice||'Contact agent'}</small></span></article>`).join(''):'<p class="empty-copy">Your wishlist is empty. Save a home while exploring to see it here.</p>'}</div></div></div></section>`;document.querySelector('#tenantBackHome').onclick=()=>location.href='/index.html?v=20260912-auth-bookings1#top';document.querySelectorAll('[data-agent-id]').forEach(button=>button.onclick=()=>openAgentProfile(button.dataset.agentId,false));document.querySelector('#editTenantProfile').onclick=()=>openTenantProfileEditor(profile);document.querySelector('#tenantBookingsProfile').onclick=loadTenantBookings;window.scrollTo({top:0,behavior:'smooth'})}
function openTenantProfileEditor(profile){openModal(`<p class="eyebrow">Tenant profile</p><h2>Edit your profile</h2><form id="tenantProfileForm"><label>Profile photo</label><input name="profilePic" type="file" accept="image/jpeg,image/png,image/webp,image/avif"><label>About you</label><textarea name="bio" maxlength="5000">${profile.bio||''}</textarea><p class="form-error" role="alert"></p><button class="primary" type="submit">Save profile</button></form>`);content.querySelector('#tenantProfileForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget;try{const csrf=(await apiJson('/api/auth/csrf')).token;const photo=form.elements.profilePic.files[0];if(photo){const data=new FormData();data.append('profilePic',photo);await apiJson('/api/tenant/profile/photo',{method:'POST',headers:{'X-CSRF-Token':csrf},body:data})}await apiJson('/api/tenant/profile',{method:'PATCH',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({bio:form.elements.bio.value})});closeModal();showToast('Profile updated');await openOwnTenantProfile();await updateAuthControls((await apiJson('/api/auth/me')).user)}catch(error){form.querySelector('.form-error').textContent=error.message}}}
async function openAgentFollowList(id,kind){const result=await apiJson(`/api/agents/${id}/${kind}`);openModal(`<p class="eyebrow">Agent network</p><h2>${kind==='followers'?'Followers':'Following'}</h2>${result.users.length?result.users.map(user=>`<button class="search-result" data-user-id="${user.id}" data-role="${user.role}">${user.role==='agent'?agentAvatar(user.profileImageUrl,user.badgeLabel,`${user.firstName} ${user.lastName}`):''}<span><strong>${user.firstName} ${user.lastName}</strong><small>${user.role==='agent'?'Open agent profile':'StayNest tenant'}</small></span></button>`).join(''):'<p>No profiles here yet.</p>'}`);content.querySelectorAll('[data-user-id]').forEach(button=>button.onclick=()=>{if(button.dataset.role!=='agent'){showToast('Tenant profiles are private');return}closeModal();openAgentProfile(button.dataset.userId,false)})}
function openAgentMessage(id,name){if(!requireAccount('message other members'))return;openModal(`<p class="eyebrow">Private message</p><h2>Message ${name}</h2><p>Start a conversation with this StayNest member.</p><form id="messageForm"><textarea name="body" maxlength="2000" required placeholder="Write a respectful message"></textarea><p class="form-error" role="alert"></p><button class="primary" type="submit">Send message <span>→</span></button></form>`);content.querySelector('#messageForm').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;try{const csrf=(await apiJson('/api/auth/csrf')).token;await apiJson('/api/messages',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({recipientId:id,body:form.elements.body.value})});closeModal();showToast('Message sent securely')}catch(error){form.querySelector('.form-error').textContent=error.message}})}
async function openAgentProfileModal(id,owner=false){if(!requireAccount('view agent profiles'))return;const result=await apiJson(`/api/agents/${id}/profile`);const {profile,posts,following}=result;const avatar=profile.profileImageUrl||profile.avatarUrl||'';const postMarkup=posts.length?posts.map(post=>`<article class="agent-post ${post.status==='pending_review'?'agent-post-pending':''}" data-post-id="${post.id}" data-liked="${post.liked?'true':'false'}" title="${post.title}">${post.status==='pending_review'?'<span class="agent-post-status">Pending review</span>':''}${post.mediaType==='video'?`<video src="${post.coverUrl||''}" muted preload="metadata"></video>`:`<img src="${post.coverUrl||''}" alt="${post.title}" loading="lazy">`}<div class="agent-post-overlay"><button class="post-like-button" data-post-like="${post.id}" aria-label="Like post">♥</button><span><b data-post-likes>${post.likes||0}</b> likes · <b data-post-views>${post.views||0}</b> views</span></div></article>`).join(''):'<div class="agent-post-empty">No published posts yet. Create a listing and it will appear here after moderation.</div>';openModal(`<div class="agent-profile"><p class="eyebrow">StayNest agent profile</p><div class="agent-profile-head"><img class="agent-profile-avatar" src="${avatar}" alt="${profile.firstName} ${profile.lastName}" onerror="this.style.display='none'"><div><h2>${profile.firstName} ${profile.lastName}${agentBadge(profile.badgeLabel)}</h2><p>${profile.bio||'StayNest property professional.'}</p><div class="agent-profile-stats"><span><strong>${posts.length}</strong>posts</span><span><strong>${profile.followers||0}</strong>followers</span><span><strong>${profile.following||0}</strong>following</span></div><small>${profile.phone||'Phone not provided'} · ${profile.email||''}</small></div></div><div class="agent-profile-actions">${owner?'<button class="primary" id="createProfilePost">Create post <span>→</span></button><button class="outline-btn" id="editProfileAction">Edit profile</button>':`<button class="primary" id="messageAgentAction">✉ Message</button><button class="outline-btn" id="followAgentAction">${following?'Unfollow':'Follow agent'}</button>`}</div><h3>Posts</h3><div class="agent-post-grid">${postMarkup}</div></div>`);setupPostEngagement(content);content.querySelector('#followAgentAction')?.addEventListener('click',async()=>{try{const csrf=(await apiJson('/api/auth/csrf')).token;await apiJson(`/api/agents/${id}/follow`,{method:following?'DELETE':'POST',headers:{'X-CSRF-Token':csrf}});showToast(following?'Agent unfollowed':'Agent followed');openAgentProfile(id,false)}catch(error){showToast(error.message)}});content.querySelector('#messageAgentAction')?.addEventListener('click',()=>openAgentMessage(id,`${profile.firstName} ${profile.lastName}`));content.querySelector('#editProfileAction')?.addEventListener('click',()=>openAgentProfileEditor(profile));content.querySelector('#createProfilePost')?.addEventListener('click',openAgentListingForm)}
async function openAgentProfile(id,owner=false){if(!requireAccount('view agent profiles'))return;document.body.classList.add('role-view');history.replaceState({},'',`/index.html?view=agent&agent=${encodeURIComponent(id)}`);const result=await apiJson(`/api/agents/${id}/profile`);const {profile,posts,following}=result;const avatar=profile.profileImageUrl||profile.avatarUrl||DEFAULT_AGENT_AVATAR;const postMarkup=posts.length?posts.map(post=>`<article class="agent-post ${post.status==='pending_review'?'agent-post-pending':''}" data-post-id="${post.id}" data-liked="${post.liked?'true':'false'}" title="${post.title}">${post.status==='pending_review'?'<span class="agent-post-status">Pending review</span>':''}${post.mediaType==='video'?`<video src="${post.coverUrl||''}" muted preload="metadata"></video>`:`<img src="${post.coverUrl||''}" alt="${post.title}" loading="lazy">`}<div class="agent-post-overlay"><button class="post-like-button" data-post-like="${post.id}" aria-label="Like post">♥</button><span><b data-post-likes>${post.likes||0}</b> likes · <b data-post-views>${post.views||0}</b> views</span></div></article>`).join(''):'<div class="agent-post-empty">No published posts yet. Create a post and it will appear here after moderation.</div>';pageMain.innerHTML=`<section class="agent-page"><div class="agent-page-top"><button class="outline-btn" id="backHome">← Explore StayNest</button><span class="eyebrow">StayNest agent</span></div><div class="agent-page-hero"><img class="agent-page-avatar" src="${avatar}" alt="${profile.firstName} ${profile.lastName}"><div class="agent-page-copy"><p class="eyebrow">Verified property professional</p><h1>${profile.firstName} ${profile.lastName}${profile.badgeLabel?` ${agentBadge(profile.badgeLabel)}`:''}</h1><p class="agent-page-bio">${profile.bio||'Curating places that feel like home.'}</p><div class="agent-page-stats"><button class="profile-stat-link" id="postsStat"><strong>${posts.length}</strong>posts</button><button class="profile-stat-link" id="followersStat"><strong>${profile.followers||0}</strong>followers</button><button class="profile-stat-link" id="followingStat"><strong>${profile.following||0}</strong>following</button></div><p class="agent-page-contact">${profile.phone||'Phone not provided'} ${profile.email?`· ${profile.email}`:''}</p><div class="agent-profile-actions">${owner?'<button class="primary" id="createProfilePost">Create post <span>→</span></button><button class="outline-btn" id="editProfileAction">Edit profile</button>':`<button class="primary" id="messageAgentAction">✉ Message</button><button class="outline-btn" id="followAgentAction">${following?'Unfollow':'Follow agent'}</button>`}</div></div></div><div class="agent-page-toolbar"><h2>Posts</h2><span>${posts.length} published ${posts.length===1?'post':'posts'}</span></div><div class="agent-post-grid">${postMarkup}</div></section>`;setupPostEngagement(pageMain);document.querySelector('#backHome').onclick=()=>{location.href='/index.html?v=20260912-agent-profile6#top'};document.querySelector('#followersStat')?.addEventListener('click',()=>openAgentFollowList(id,'followers'));document.querySelector('#followingStat')?.addEventListener('click',()=>openAgentFollowList(id,'following'));document.querySelector('#messageAgentAction')?.addEventListener('click',()=>openAgentMessage(id,`${profile.firstName} ${profile.lastName}`));document.querySelector('#followAgentAction')?.addEventListener('click',async()=>{try{const csrf=(await apiJson('/api/auth/csrf')).token;await apiJson(`/api/agents/${id}/follow`,{method:following?'DELETE':'POST',headers:{'X-CSRF-Token':csrf}});showToast(following?'Agent unfollowed':'Agent followed');openAgentProfile(id,false)}catch(error){showToast(error.message)}});document.querySelector('#editProfileAction')?.addEventListener('click',()=>openAgentProfileEditor(profile));document.querySelector('#createProfilePost')?.addEventListener('click',openAgentListingForm);window.scrollTo({top:0,behavior:'smooth'})}
function openAgentProfileEditor(profile){openModal(`<p class="eyebrow">Agent profile</p><h2>Manage your profile</h2><form id="profileForm"><label>Profile photo</label><input name="profilePic" type="file" accept="image/jpeg,image/png,image/webp,image/avif"><label>Phone</label><input name="phone" value="${profile.phone||''}"><label>Bio</label><textarea name="bio" maxlength="5000">${profile.bio||''}</textarea><p class="form-error" role="alert"></p><button class="primary" type="submit">Save profile</button></form>`);content.querySelector('form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,errorBox=form.querySelector('.form-error');try{const csrf=(await apiJson('/api/auth/csrf')).token;const photo=form.elements.profilePic.files[0];if(photo){const photoData=new FormData();photoData.append('profilePic',photo);await apiJson('/api/agent/profile/photo',{method:'POST',headers:{'X-CSRF-Token':csrf},body:photoData})}await apiJson('/api/agent/profile',{method:'PATCH',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({phone:form.elements.phone.value,bio:form.elements.bio.value})});closeModal();showToast('Profile updated');await openOwnAgentProfile()}catch(error){errorBox.textContent=error.message}})}
function openAgentListingForm(){openModal(`<p class="eyebrow">Agent workspace</p><h2>Create a listing</h2><p>Your registration document and at least one estate image or video are required. Every post is moderated before guests can see it.</p><form id="agentListingForm" enctype="multipart/form-data"><label>Title</label><input name="title" required><label>Description / caption</label><textarea name="description" required></textarea><label>Address</label><input name="addressLine1" required><label>City</label><input name="city" required><label>Rental duration</label><select name="rentalMode"><option value="short_term">Nightly</option><option value="long_term">Monthly</option><option value="both">Nightly, monthly, or yearly</option></select><label>Nightly price</label><input name="nightlyPrice" type="number" min="1" step="0.01"><label>Monthly price</label><input name="monthlyPrice" type="number" min="1" step="0.01"><label>Yearly price</label><input name="yearlyPrice" type="number" min="1" step="0.01"><label>Registration document</label><input name="document" type="file" accept=".pdf,image/jpeg,image/png" required><label>Estate image or video</label><input name="media" type="file" accept="image/jpeg,image/png,image/webp,image/avif,video/mp4,video/webm" multiple required><label>Media caption</label><input name="caption0" maxlength="255" placeholder="Describe the first image or video"><p class="form-error" role="alert"></p><button class="primary" type="submit">Submit for review <span>→</span></button></form>`);content.querySelector('form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;const error=form.querySelector('.form-error');try{const csrf=await apiJson('/api/auth/csrf');await apiJson('/api/agent/listings',{method:'POST',headers:{'X-CSRF-Token':csrf.token},body:new FormData(form)});closeModal();showToast('Listing submitted for moderation.');await openOwnAgentProfile()}catch(error){form.querySelector('.form-error').textContent=error.message}})}
async function loadTenantBookings(){const result=await apiJson('/api/account/bookings');openModal(`<p class="eyebrow">Tenant workspace</p><h2>My bookings</h2><p class="search-note">Agents review pending requests. You will receive a notification when a booking is approved or declined.</p>${result.bookings.length?result.bookings.map(booking=>`<div class="feature-list"><div><b>${booking.status.replaceAll('_',' ')}</b><span><strong>${booking.title}</strong><small>${booking.check_in} to ${booking.check_out} · ${booking.currency} ${booking.total_amount} · Booking ${booking.booking_code}</small></span></div></div>`).join(''):'<p class="empty-copy">You have no bookings yet. Search for a published home to send a request.</p>'}`)}
async function loadAgentBookings(){const result=await apiJson('/api/agent/bookings');openModal(`<p class="eyebrow">Agent workspace</p><h2>Booking requests</h2>${result.bookings.length?result.bookings.map(booking=>`<div class="booking-request"><div><strong>${booking.title}</strong><small>${booking.firstName} ${booking.lastName} · ${booking.email||booking.phone||'Contact available in profile'}<br>${booking.checkIn} to ${booking.checkOut} · ${booking.guests} guest(s) · ${booking.currency} ${booking.totalAmount}</small></div>${booking.status==='pending'?`<div class="booking-actions"><button class="primary" data-booking-decision="${booking.id}" data-status="confirmed">Approve</button><button class="outline-btn" data-booking-decision="${booking.id}" data-status="declined">Decline</button><button class="icon-btn" data-booking-message="${booking.tenantId}" data-name="${booking.firstName} ${booking.lastName}" aria-label="Message tenant">✉</button></div>`:`<span class="booking-status">${booking.status}</span>`}</div>`).join(''):'<p class="empty-copy">No booking requests yet.</p>'}`);content.querySelectorAll('[data-booking-decision]').forEach(button=>button.onclick=async()=>{try{const csrf=(await apiJson('/api/auth/csrf')).token;await apiJson(`/api/agent/bookings/${button.dataset.bookingDecision}/decision`,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({status:button.dataset.status})});showToast(button.dataset.status==='confirmed'?'Booking approved and tenant notified':'Booking declined and tenant notified');loadAgentBookings()}catch(error){showToast(error.message)}});content.querySelectorAll('[data-booking-message]').forEach(button=>button.onclick=()=>openAgentMessage(button.dataset.bookingMessage,button.dataset.name))}
async function openMessages(){try{const result=await apiJson('/api/messages');openModal(`<p class="eyebrow">StayNest inbox</p><h2>Your messages</h2><p class="modal-intro">Continue conversations with tenants and agents from one secure inbox.</p><div class="message-list">${result.conversations.length?result.conversations.map(item=>`<button class="message-thread ${Number(item.unread)>0?'unread':''}" data-conversation-id="${item.conversationId}" data-recipient-id="${item.otherUserId}"><span><strong>${item.otherFirstName} ${item.otherLastName}</strong><small>${item.lastMessage||'No messages yet'}</small></span><time>${item.lastMessageAt?new Date(item.lastMessageAt).toLocaleString():''}</time></button>`).join(''):'<p class="empty-copy">Your inbox is empty. Open an agent profile to start a conversation.</p>'}</div>`);content.querySelectorAll('[data-conversation-id]').forEach(thread=>thread.addEventListener('click',()=>openConversation(thread.dataset.conversationId,thread.querySelector('strong').textContent,thread.dataset.recipientId)))}catch(error){showToast(error.message)}}
async function openConversation(id,name,recipientId){try{const result=await apiJson(`/api/messages/${id}`);openModal(`<p class="eyebrow">Conversation</p><h2>${escapeHtml(name)}</h2><p class="conversation-participants"><strong>From:</strong> ${escapeHtml(name)} <span>↔</span> <strong>To:</strong> ${escapeHtml(currentUser?.firstName||'You')} ${escapeHtml(currentUser?.lastName||'')}</p><div class="conversation-list">${result.messages.map(message=>`<div class="conversation-message ${Number(message.senderId)===Number(currentUser.id)?'mine':''}"><p>${escapeHtml(message.body)}</p><small>${new Date(message.createdAt).toLocaleString()}</small></div>`).join('')}</div><form id="replyMessageForm"><textarea name="body" maxlength="2000" required placeholder="Write a reply to ${name}"></textarea><p class="form-error" role="alert" aria-live="polite"></p><button class="primary" type="submit">Send reply <span>→</span></button></form>`);content.querySelector('#replyMessageForm').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;try{const csrf=(await apiJson('/api/auth/csrf')).token;await apiJson('/api/messages',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({recipientId:recipientId||result.messages.find(message=>Number(message.senderId)!==Number(currentUser.id))?.senderId,body:form.elements.body.value})});await openConversation(id,name,recipientId)}catch(error){form.querySelector('.form-error').textContent=error.message}})}catch(error){showToast(error.message)}}
async function openNotifications(){const result=await apiJson('/api/notifications');openModal(`<p class="eyebrow">StayNest updates</p><h2>Notifications</h2><p class="modal-intro">Important updates about your account, bookings, messages, and agent activity.</p><button class="primary small notification-messages" type="button">Open messages</button>${result.notifications.length?result.notifications.map(notification=>`<article class="notification-item ${notification.readAt?'':'unread'}"><strong>${escapeHtml(notification.title)}</strong><p>${escapeHtml(notification.body)}</p><small>${new Date(notification.createdAt).toLocaleString()}</small></article>`).join(''):'<p class="empty-copy">You are all caught up. New updates will appear here.</p>'}`);content.querySelector('.notification-messages').onclick=openMessages;if(result.unread){const csrf=(await apiJson('/api/auth/csrf')).token;await apiJson('/api/notifications/read',{method:'POST',headers:{'X-CSRF-Token':csrf}});document.querySelector('#notificationBadge').hidden=true}}
async function openSettings(){const me=(await apiJson('/api/auth/me')).user;if(me?.roles?.includes('agent')){try{return await openAgentSettings()}catch(error){showToast(`Agent settings could not be loaded: ${error.message}`);return}}openModal(`<p class="eyebrow">Account settings</p><h2>Your StayNest settings</h2><p>Manage your tenant profile, notifications, and account access.</p><div class="settings-list"><button class="outline-btn" id="tenantProfileSetting">Edit profile and photo</button><button class="outline-btn" id="tenantNotificationsSetting">Notification center</button><button class="outline-btn" id="tenantBookingsSetting">Booking history and status</button></div>`);content.querySelector('#tenantProfileSetting').onclick=openOwnTenantProfile;content.querySelector('#tenantNotificationsSetting').onclick=openNotifications;content.querySelector('#tenantBookingsSetting').onclick=loadTenantBookings}
async function openAgentSettings(){const result=await apiJson('/api/agent/settings');const isMain=!result.currentUser.isSubAgent;openModal(`<p class="eyebrow">Agent settings</p><h2>${isMain?'Manage your agent account':'Your delegated access'}</h2><p>${isMain?'Control your profile, security, notifications, and remote sub-agent access.':'This account is labeled as a sub-agent. You can only use the permissions assigned by the main agent.'}</p>${!isMain?`<div class="access-summary"><strong>${result.currentUser.accountLabel||'Sub-agent'}</strong><small>Allowed actions: ${result.currentUser.permissions.join(', ')||'None'}</small></div>`:`<div class="settings-list"><button class="outline-btn" id="agentProfileSetting">Edit public profile</button><button class="outline-btn" id="agentBookingsSetting">Booking requests</button><button class="primary" id="agentSubagentSetting">+ Add and manage sub-agents</button></div><div class="subagent-list">${result.subagents.length?result.subagents.map(agent=>`<div class="subagent-row"><span><strong>${agent.label}</strong><small>${agent.firstName} ${agent.lastName} · ${agent.email} · ${agent.status}</small></span><button class="outline-btn" data-edit-subagent="${agent.id}">Access</button></div>`).join(''):'<p class="empty-copy">No sub-agents have been created yet. Use “Add and manage sub-agents” to create the first one.</p>'}</div>`}`);content.querySelector('#agentProfileSetting')?.addEventListener('click',openOwnAgentProfile);content.querySelector('#agentBookingsSetting')?.addEventListener('click',loadAgentBookings);content.querySelector('#agentSubagentSetting')?.addEventListener('click',()=>openSubagentEditor(result));content.querySelectorAll('[data-edit-subagent]').forEach(button=>button.onclick=()=>openSubagentAccessEditor(result,Number(button.dataset.editSubagent)))}
function openSubagentEditor(settings){openModal(`<p class="eyebrow">Agent actions</p><h2>Add a sub-agent</h2><p>Sub-agents use their own secure login and can work remotely on this main account. Select at least one allowed action.</p><form id="subagentForm" enctype="multipart/form-data"><label>Account label</label><input name="label" placeholder="Nairobi bookings assistant" required><label>First name</label><input name="firstName" required><label>Last name</label><input name="lastName" required><label>Email</label><input name="email" type="email" required><label>Phone</label><input name="phone" type="tel"><label>Location</label><input name="location" placeholder="City or region"><label>Profile picture</label><input name="profilePic" type="file" accept="image/jpeg,image/png,image/webp,image/avif"><label>Password</label><input name="password" type="password" minlength="12" required><fieldset class="permission-grid"><legend>Allowed roles and actions</legend>${settings.permissions.map(permission=>`<label><input type="checkbox" name="permission" value="${permission.key}"> ${permission.label}</label>`).join('')}</fieldset><p class="form-error" role="alert"></p><button class="primary" type="submit">Create sub-agent</button></form>`);content.querySelector('#subagentForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,selected=[...form.querySelectorAll('[name="permission"]:checked')].map(input=>input.value),errorNode=form.querySelector('.form-error'),button=form.querySelector('button[type="submit"]');if(!selected.length){errorNode.textContent='Choose at least one action before creating this sub-agent';return}button.disabled=true;try{const csrf=(await apiJson('/api/auth/csrf')).token;const data=new FormData(form);data.set('permissions',JSON.stringify(selected));const result=await apiJson('/api/agent/subagents',{method:'POST',headers:{'X-CSRF-Token':csrf},body:data});closeModal();openModal(`<p class="eyebrow">Sub-agent created</p><h2>${result.label} is ready</h2><p>${result.message}</p><div class="feature-list"><div><b>Login email</b><span>${result.email}<small>The password is known only to the sub-agent and is not shown here.</small></span></div><div><b>Access granted</b><span>${result.permissionLabels.join(' · ')}</span></div></div><p class="search-note">The new sub-agent has received a StayNest notification with their sign-in email and assigned actions. Share the password securely; it is never displayed here.</p><button class="primary" id="viewSubagents">View sub-agents <span>→</span></button>`);content.querySelector('#viewSubagents').onclick=()=>openAgentSettings()}catch(error){errorNode.textContent=error.message;button.disabled=false}}}
function openSubagentAccessEditor(settings,id){const agent=settings.subagents.find(item=>item.id===id);if(!agent)return;openModal(`<p class="eyebrow">Agent actions</p><h2>${agent.label}</h2><p>Check or uncheck the actions this sub-agent may perform. At least one action is required.</p><form id="accessForm"><fieldset class="permission-grid">${settings.permissions.map(permission=>`<label><input type="checkbox" name="permission" value="${permission.key}" ${agent.permissions.includes(permission.key)?'checked':''}> ${permission.label}</label>`).join('')}</fieldset><label>Status</label><select name="status"><option value="active" ${agent.status==='active'?'selected':''}>Active</option><option value="suspended" ${agent.status==='suspended'?'selected':''}>Suspended</option><option value="revoked" ${agent.status==='revoked'?'selected':''}>Revoked</option></select><p class="form-error" role="alert"></p><button class="primary" type="submit">Save access</button></form>`);content.querySelector('#accessForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,permissions=[...form.querySelectorAll('[name="permission"]:checked')].map(input=>input.value),errorNode=form.querySelector('.form-error');if(!permissions.length){errorNode.textContent='A sub-agent must retain at least one permission';return}try{const csrf=(await apiJson('/api/auth/csrf')).token;await apiJson(`/api/agent/subagents/${id}`,{method:'PATCH',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({permissions,status:form.elements.status.value})});closeModal();showToast('Sub-agent access updated');await openAgentSettings()}catch(error){errorNode.textContent=error.message}}}
async function openDiscover(){try{const result=await apiJson('/api/agents');openModal(`<div class="agent-marketplace"><div class="agent-marketplace-head"><div><p class="eyebrow">StayNest agent marketplace</p><h2>Find a trusted agent</h2><p class="search-note">Browse active agents ranked by followers, published homes, ratings, and engagement.</p></div><span class="status-pill">${result.agents.length} available</span></div><div class="agent-directory">${result.agents.length?result.agents.map(agent=>`<button class="search-result agent-directory-item" data-agent-id="${agent.id}">${agentAvatar(agent.profileImageUrl,agent.badgeLabel,`${agent.firstName} ${agent.lastName}`)}<span><strong>${agent.firstName} ${agent.lastName}${agent.badgeLabel?` ${agentBadge(agent.badgeLabel)}`:''}</strong><small>${agent.bio||'StayNest property professional'} · ${agent.listings} homes · ★ ${Number(agent.rating).toFixed(1)} · ${agent.followers||0} followers</small></span><em>#${result.agents.indexOf(agent)+1}</em></button>`).join(''):'<p class="empty-copy">No active agents are available yet.</p>'}</div></div>`);content.querySelectorAll('[data-agent-id]').forEach(button=>button.onclick=()=>{closeModal();openAgentProfile(button.dataset.agentId,false)})}catch(error){if(error.message.includes('401')){auth('login')}else showToast(error.message)}}
async function updateAuthControls(user){currentUser=user||null;document.body.classList.toggle('agent-marketplace-view',Boolean(user?.roles?.includes('agent')));const login=document.querySelector('[data-auth-control="login"]'),signup=document.querySelector('[data-auth-control="signup"]'),agentButton=document.querySelector('#agentProfileControl'),agentAvatar=document.querySelector('#agentProfileAvatar'),agentName=document.querySelector('#agentProfileName'),tenantButton=document.querySelector('#tenantProfileControl'),tenantAvatar=document.querySelector('#tenantProfileAvatar'),tenantName=document.querySelector('#tenantProfileName'),notificationButton=document.querySelector('#notificationControl'),notificationBadge=document.querySelector('#notificationBadge'),settingsButton=document.querySelector('#settingsControl');if(!login||!signup)return;if(user){login.textContent='Sign out';login.setAttribute('aria-label','Sign out of StayNest');login.dataset.authAction='logout';signup.hidden=true;notificationButton.hidden=false;notificationButton.onclick=openNotifications;settingsButton.hidden=false;settingsButton.onclick=openSettings;const refreshNotifications=async()=>{try{const notifications=await apiJson('/api/notifications');notificationBadge.textContent=notifications.unread>99?'99+':notifications.unread;notificationBadge.hidden=!notifications.unread}catch(error){console.warn('Notifications unavailable:',error.message)}};await refreshNotifications();clearInterval(window.stayNestNotificationTimer);window.stayNestNotificationTimer=setInterval(refreshNotifications,15000);login.onclick=async()=>{try{const csrf=await apiJson('/api/auth/csrf');await apiJson('/api/auth/logout',{method:'POST',headers:{'X-CSRF-Token':csrf.token}});clearInterval(window.stayNestNotificationTimer);location.reload()}catch(error){showToast(error.message)}};if(agentButton)agentButton.hidden=!user.roles?.includes('agent');if(tenantButton)tenantButton.hidden=!user.roles?.includes('tenant');if(user.roles?.includes('agent')&&agentButton){agentName.textContent=user.isSubAgent?`${user.firstName||'Agent'} · ${user.accountLabel||'Sub-agent'}`:user.firstName||'Agent';agentAvatar.src=DEFAULT_AGENT_AVATAR;agentButton.onclick=()=>openAgentProfile(user.mainAgentId||user.id,!user.isSubAgent);try{const profile=(await apiJson(`/api/agents/${user.mainAgentId||user.id}/profile`)).profile;agentAvatar.src=profile.profileImageUrl||profile.avatarUrl||DEFAULT_AGENT_AVATAR}catch(error){console.warn('Agent profile details unavailable:',error.message)}}if(user.roles?.includes('tenant')&&tenantButton){tenantName.textContent=user.firstName||'Tenant';tenantAvatar.src=DEFAULT_AGENT_AVATAR;tenantButton.onclick=openOwnTenantProfile;try{const profile=(await apiJson('/api/tenant/profile')).profile;tenantAvatar.src=profile.avatarUrl||DEFAULT_AGENT_AVATAR;tenantName.textContent=profile.firstName||user.firstName||'Tenant'}catch(error){console.warn('Tenant profile details unavailable:',error.message)}}if(!user.roles?.includes('agent')&&!user.roles?.includes('tenant')&&tenantButton){tenantButton.hidden=false;tenantName.textContent=user.firstName||'Account';tenantAvatar.src=DEFAULT_AGENT_AVATAR;tenantButton.onclick=openSettings}}else{clearInterval(window.stayNestNotificationTimer);login.textContent='Log in';login.setAttribute('aria-label','Log in to StayNest');signup.hidden=false;notificationButton.hidden=true;settingsButton.hidden=true;login.dataset.authAction='login';login.onclick=()=>auth('login');signup.onclick=()=>auth('signup');if(agentButton)agentButton.hidden=true;if(tenantButton)tenantButton.hidden=true}}
document.querySelectorAll('[data-open]').forEach(b=>b.addEventListener('click',()=>auth(b.dataset.open)));document.querySelector('#modalClose').addEventListener('click',closeModal);modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal.classList.contains('open'))closeModal()});document.querySelectorAll('.chip').forEach(b=>b.addEventListener('click',()=>{document.querySelector('.chip.active').classList.remove('active');b.classList.add('active');render(b.dataset.filter)}));document.querySelector('#viewAll').addEventListener('click',()=>{document.querySelector('[data-filter="all"]').click()});render();
document.querySelector('#discoverAction').addEventListener('click',openDiscover);
function searchLabel(type){return {estate:'Homes',location:'Homes near',price:'Homes under',agent:'Agents and sub-agents',tenant:'Tenants'}[type]||'Search results'}
async function runSearch(){const input=document.querySelector('#locationInput'),type=document.querySelector('#searchType').value,query=input.value.trim();if((type==='agent'||type==='tenant')&&!requireAccount(`search registered ${type}s`))return;const valid=type==='price'?/^\$?\s*\d[\d,\s]*(\.\d+)?$/.test(query):query.length>=2;if(!valid){showToast(type==='price'?'Enter a maximum price, such as 1200':'Enter at least two characters to search');input.focus();return}try{const result=await apiJson(`/api/search?type=${encodeURIComponent(type)}&q=${encodeURIComponent(query)}`);if(type==='agent'){openModal(`<p class="eyebrow">People</p><h2>${searchLabel(type)} matching “${query}”</h2><p class="search-note">Sorted by relevance, active listings, ratings, trusted engagement, and delegated account labels.</p>${result.agents.length?result.agents.map(agent=>`<button class="search-result" data-agent-id="${agent.id}"><img src="${agent.profileImageUrl||DEFAULT_AGENT_AVATAR}" alt=""><span><strong>${agent.firstName} ${agent.lastName}${agent.badgeLabel?` ${agentBadge(agent.badgeLabel)}`:''}</strong><small>${agent.subagentLabel?`Sub-agent · ${agent.subagentLabel}`:(agent.bio||'StayNest agent')} · ${agent.followers||0} followers</small></span></button>`).join(''):'<p class="empty-copy">No agents or sub-agents matched that search. Try a full name, account label, or part of their bio.</p>'}`);content.querySelectorAll('[data-agent-id]').forEach(button=>button.onclick=()=>{closeModal();openAgentProfile(button.dataset.agentId,false)})}else if(type==='tenant'){openModal(`<p class="eyebrow">People</p><h2>${searchLabel(type)} matching “${query}”</h2><p class="search-note">Tenant discovery shows names only. Private profile details remain protected.</p>${result.tenants.length?result.tenants.map(tenant=>`<div class="search-result"><span><strong>${tenant.firstName} ${tenant.lastName}</strong><small>Registered StayNest tenant</small></span></div>`).join(''):'<p class="empty-copy">No tenants matched that name.</p>'}`)}else{openModal(`<p class="eyebrow">StayNest search</p><h2>${type==='price'?`${searchLabel(type)} ${query.replace(/[$,\s]/g,'')}`:`${searchLabel(type)} “${query}”`}</h2><p class="search-note">Ranked by relevance, location, freshness, ratings, saves, views, and likes.</p>${result.listings.length?result.listings.map(listing=>`<button class="search-result listing-result" data-listing='${JSON.stringify(listing).replace(/'/g,'&#39;')}'><img src="${listing.coverUrl||DEFAULT_AGENT_AVATAR}" alt=""><span><strong>${listing.title}</strong><small>${listing.city} · ${listing.currency} ${listing.nightlyPrice||listing.monthlyPrice||listing.yearlyPrice||'Contact agent'} · ${listing.rating?`★ ${listing.rating}`:'New listing'}</small></span></button>`).join(''):'<p class="empty-copy">No published homes matched. Try a nearby location, property type, or a higher price.</p>'}`);content.querySelectorAll('[data-listing]').forEach(button=>button.onclick=()=>{const listing=JSON.parse(button.dataset.listing);closeModal();openListing({...listing,title:listing.title,location:listing.city,price:`${listing.currency} ${listing.nightlyPrice||listing.monthlyPrice||listing.yearlyPrice||'Contact agent'}`,rating:listing.rating||'New',reviews:listing.reviewCount||0,image:listing.coverUrl||DEFAULT_AGENT_AVATAR,tag:'Search result'})})}}catch(error){showToast(error.message)}}
document.querySelector('#searchBtn').onclick=runSearch;document.querySelector('#locationInput').addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();runSearch()}});document.querySelector('#exploreAgentsNav')?.addEventListener('click',event=>{event.preventDefault();openDiscover()});document.querySelector('#searchType').addEventListener('change',event=>{const input=document.querySelector('#locationInput');input.placeholder=event.target.value==='price'?'Maximum price, e.g. 1200':event.target.value==='agent'?'Search agent name or bio':event.target.value==='tenant'?'Search tenant name':'Search homes, places, or property types'});
updatePersonalGreeting(null);const requestedParams=new URLSearchParams(location.search),requestedAgentId=requestedParams.get('agent'),requestedView=requestedParams.get('view');apiJson('/api/auth/me').then(result=>{updatePersonalGreeting(result.user);updateAuthControls(result.user);if(requestedAgentId)openAgentProfile(requestedAgentId,requestedView==='agent'&&String(result.user.id)===String(requestedAgentId)).catch(error=>showToast(error.message));else if(requestedView==='tenant'&&result.user.roles?.includes('tenant'))openOwnTenantProfile().catch(error=>showToast(error.message))}).catch(()=>{updateAuthControls(null);if(requestedAgentId||requestedView)requireAccount('view your StayNest profile')});

function initScrollSequence(){const section=document.querySelector('.sequence-section'),canvas=document.querySelector('#sequenceCanvas'),status=document.querySelector('#sequenceStatus'),progress=document.querySelector('#sequenceProgress');if(!section||!canvas)return;const context=canvas.getContext('2d',{alpha:false});const count=Number(section.dataset.frameCount)||240,padding=Number(section.dataset.framePadding)||3,path=section.dataset.framePath||'/assets/frame_',extension=section.dataset.frameExtension||'.jpg',frames=Array.from({length:count},(_,index)=>{const image=new Image();image.decoding='async';image.src=`${path}${String(index+1).padStart(padding,'0')}${extension}`;return image});let loaded=0,lastFrame=-1,pendingFrame=null,drawQueued=false,targetProgress=0,displayProgress=0,animationFrame=0;const drawFrame=index=>{const image=frames[index];if(!image||!image.complete||!image.naturalWidth)return;const width=canvas.clientWidth,height=canvas.clientHeight,dpr=Math.min(window.devicePixelRatio||1,2),pixelWidth=Math.round(width*dpr),pixelHeight=Math.round(height*dpr);if(canvas.width!==pixelWidth||canvas.height!==pixelHeight){canvas.width=pixelWidth;canvas.height=pixelHeight;context.setTransform(dpr,0,0,dpr,0,0)}const scale=Math.max(width/image.naturalWidth,height/image.naturalHeight),drawWidth=image.naturalWidth*scale,drawHeight=image.naturalHeight*scale;context.fillStyle='#10251f';context.fillRect(0,0,width,height);context.drawImage(image,(width-drawWidth)/2,(height-drawHeight)/2,drawWidth,drawHeight);lastFrame=index};const queueFrame=index=>{pendingFrame=index;if(drawQueued)return;drawQueued=true;requestAnimationFrame(()=>{drawQueued=false;if(pendingFrame!==null){drawFrame(pendingFrame);pendingFrame=null}})};const animate=()=>{const difference=targetProgress-displayProgress;displayProgress+=difference*.18;if(Math.abs(difference)<.0005)displayProgress=targetProgress;const frameIndex=Math.min(count-1,Math.round(displayProgress*(count-1)));if(frameIndex!==lastFrame)queueFrame(frameIndex);if(progress)progress.style.width=`${displayProgress*100}%`;if(Math.abs(targetProgress-displayProgress)>.0005){animationFrame=requestAnimationFrame(animate)}else{animationFrame=0}};const requestAnimation=()=>{if(!animationFrame)animationFrame=requestAnimationFrame(animate)};const update=()=>{const scrollDistance=Math.max(1,section.offsetHeight-window.innerHeight);targetProgress=Math.max(0,Math.min(1,(window.scrollY-section.offsetTop)/scrollDistance));requestAnimation()};const resize=()=>{if(lastFrame>=0){lastFrame=-1;update()}};frames.forEach(image=>image.addEventListener('load',()=>{loaded+=1;if(loaded===count){status.textContent='Scroll to explore';drawFrame(0)}else if(loaded%24===0)status.textContent=`Loading visual tour… ${Math.round(loaded/count*100)}%`},{once:true}));frames.forEach(image=>image.addEventListener('error',()=>{status.textContent='Some frames could not be loaded';},{once:true}));window.addEventListener('scroll',update,{passive:true});window.addEventListener('resize',resize);window.addEventListener('orientationchange',resize);update();if(frames[0].complete)drawFrame(0)}
function initCinematicMotion(){const reduceMotion=window.matchMedia('(prefers-reduced-motion: reduce)').matches;const revealItems=document.querySelectorAll('.cinema-section,.cinema-card,.listing-card,.split-image,.split-copy,.host-banner');revealItems.forEach(item=>item.classList.add('reveal-on-scroll'));if(reduceMotion){revealItems.forEach(item=>item.classList.add('is-visible'))}else{const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target)}}),{threshold:.14,rootMargin:'0px 0px -8%'});revealItems.forEach(item=>observer.observe(item))}document.querySelectorAll('[data-tilt]').forEach(card=>{card.addEventListener('pointermove',event=>{if(reduceMotion||event.pointerType==='touch')return;const rect=card.getBoundingClientRect(),x=(event.clientX-rect.left)/rect.width-.5,y=(event.clientY-rect.top)/rect.height-.5;card.style.transform=`perspective(1100px) rotateX(${y*-4}deg) rotateY(${x*5}deg) translateY(-5px)`});card.addEventListener('pointerleave',()=>{card.style.transform=''})});const track=document.querySelector('[data-smooth-track]');if(track&&!reduceMotion)track.addEventListener('wheel',event=>{if(Math.abs(event.deltaY)>Math.abs(event.deltaX)){event.preventDefault();track.scrollBy({left:event.deltaY*.85,behavior:'smooth'})}},{passive:false});const heroImage=document.querySelector('.hero-image');if(heroImage&&!reduceMotion){let ticking=false;window.addEventListener('scroll',()=>{if(ticking)return;ticking=true;requestAnimationFrame(()=>{const offset=Math.max(-20,Math.min(20,window.scrollY*.035));heroImage.style.transform=`translate3d(0,${offset}px,0) scale(1.015)`;ticking=false})},{passive:true})}}
async function loadAgentShowcase(){const track=document.querySelector('[data-smooth-track]');if(!track)return;try{const result=await apiJson('/api/showcase/posts');if(!result.posts?.length)return;track.innerHTML=result.posts.map((post,index)=>{const creator=post.subagentLabel?`${post.firstName} ${post.lastName} · ${post.subagentLabel}`:`${post.firstName} ${post.lastName}`;const price=post.nightlyPrice?`${post.currency} ${post.nightlyPrice} / night`:post.monthlyPrice?`${post.currency} ${post.monthlyPrice} / month`:post.yearlyPrice?`${post.currency} ${post.yearlyPrice} / year`:'Contact agent';const media=escapeHtml(safeMediaUrl(post.coverUrl||'/assets/ezgif-frame-018.jpg'));return `<article class="cinema-card ${index%2?'cinema-card-wide':'cinema-card-tall'}" data-tilt data-showcase-post="${escapeHtml(post.id)}"><img src="${media}" alt="${escapeHtml(post.title)}" loading="lazy"><div class="cinema-card-copy"><a class="cinema-card-author" href="/index.html?view=agent&amp;agent=${encodeURIComponent(post.agentId)}" aria-label="Open ${escapeHtml(creator)} profile">${escapeHtml(creator)}</a><span>${escapeHtml(post.city)}</span><strong>${escapeHtml(post.title)}</strong><small>${escapeHtml(price)} · ${post.rating?`★ ${escapeHtml(post.rating)}`:'New post'} · ${escapeHtml(post.likes||0)} likes</small></div></article>`}).join('');track.querySelectorAll('[data-showcase-post]').forEach(card=>card.addEventListener('click',event=>{if(event.target.closest('a'))return;const post=result.posts.find(item=>String(item.id)===card.dataset.showcasePost);if(post)openListing({title:post.title,location:post.city,price:post.nightlyPrice||post.monthlyPrice||post.yearlyPrice,rating:post.rating||'New',reviews:post.reviewCount||0,image:safeMediaUrl(post.coverUrl||'/assets/ezgif-frame-018.jpg'),tag:'Agent post'})}));initCinematicMotion()}catch(error){console.warn('Agent showcase unavailable:',error.message)}}
initScrollSequence();
loadAgentShowcase();
initCinematicMotion();
